 "new_string": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    # Identify contiguous non-background runs on the perimeter as guide bars.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] != bg:
                color, a = grid[r][c], c
                while c < w and grid[r][c] == color: c += 1
                if c-a >= 2: bars.append((r, a, c-1, color))
            else: c += 1
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] != bg:
                color, a = grid[r][c], r
                while r < h and grid[r][c] == color: r += 1
                if r-a >= 2: bars.append((c, a, r-1, color))
            else: r += 1
    # Project isolated interior marks toward a collinear perimeter bar.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or any((rr,cc)!=(r,c) and grid[rr][cc]==color for rr in range(h) for cc in range(w)):
                continue
            targets=[]
            for br,a,b,_ in bars:
                if br in (0,h-1) and a <= c <= b:
                    targets.append((abs(br-r), 0 if br < r else 1, br, c))
                elif br in (0,w-1) and a <= r <= b:
                    targets.append((abs(br-c), 0 if br < c else 1, r, br))
            if not targets: continue
            _,_,tr,tc=min(targets)
            dr=(tr>r)-(tr<r); dc=(tc>c)-(tc<c)
            y,x=r+dr,c+dc
            while (y,x)!=(tr,tc):
                if out[y][x]==bg: out[y][x]=color
                y+=dr; x+=dc
            out[r][c]=4
    return out"
